SACT.upgrade = el => go(el.dataset.t === "company" ? "kabinet/kompaniya" : "kabinet/pro");
SFORM.upgrade = (f, fd) => { const c = cli(), org = String(fd.get("org") || "").trim(); if (f.dataset.t === "company") { c.type = "company"; c.company = c.company || { name: org || c.name, inn: "", budget: 0, address: "", members: [{ id: uid("cm"), name: c.name, phone: c.phone, role: "Administrator" }] }; if (org) c.company.name = org; } else { c.type = "manager"; c.agency = org || c.agency || ""; c.team = c.team || []; } logS(`${c.name}: hisob turi — ${CL_TYPES[c.type]}`); commitS(); toastS(L("Hisob yangilandi", "Аккаунт обновлён", "Account updated")); };
const W_TR = [[/^(CF-\d+|RB-\d+) · (.+) — (\d+)% cashback$/, "$1 · $2 — кэшбэк $3%", "$1 · $2 — $3% cashback"], [/^(CF-\d+|RB-\d+) · (.+) — (\d+)% ball$/, "$1 · $2 — баллы $3%", "$1 · $2 — $3% points"], [/^(\S+) buyurtmasiga chegirma$/, "Скидка на заказ $1", "Discount on order $1"], [/^(\S+) ijarasiga chegirma$/, "Скидка на аренду $1", "Discount on rental $1"], [/^Do‘st taklifi: (.+) ro‘yxatdan o‘tdi$/, "Приглашение: $1 зарегистрировался", "Referral: $1 signed up"], [/^(.+) taklifi bilan ro‘yxatdan o‘tish bonusi$/, "Бонус за регистрацию по приглашению $1", "Sign-up bonus via $1’s invite"], [/^Kartaga yechish: (.+)$/, "Вывод на карту: $1", "Withdrawal to card: $1"], [/^(.+) — 5% cashback$/, "$1 — кэшбэк 5%", "$1 — 5% cashback"]];
const wTr = t => { if (S.lang === "uz") return t; for (const [rx, ru, en] of W_TR) if (rx.test(t)) return t.replace(rx, S.lang === "ru" ? ru : en); return t; };

